const out = $input.item.json || {};
const stdout = String(out.stdout || '');
const stderr = String(out.stderr || '');
const exitCode = out.code ?? out.exitCode ?? null;
const ok = !out.error && (exitCode === 0 || exitCode === null) && stdout.includes('OK:');

if (!ok) {
  console.error('[Nextcloud-Backup] FEHLGESCHLAGEN:', stderr || out.error || stdout);
} else {
  console.log('[Nextcloud-Backup] Erfolgreich:', stdout);
}

return [{ json: { ok, stdout, stderr, exitCode, checkedAt: new Date().toISOString() } }];
